<html lang="ar" dir="rtl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>طبقات الأرض الجيولوجية</title>
<style>
  *,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
  :root{
    --bg:#0a0f1e;--card:#111827;--text:#e2e8f0;--text-dim:#94a3b8;
    --crust:#22c55e;--mantle:#f59e0b;--core:#ef4444;--inner-core:#fbbf24;
  }
  body{
    font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Noto Sans Arabic",Arial,sans-serif;
    background:var(--bg);color:var(--text);line-height:1.8;
    min-height:100vh;overflow-x:hidden;
  }

  /* Stars background */
  body::before{
    content:'';position:fixed;inset:0;z-index:0;
    background:radial-gradient(1px 1px at 10% 20%,rgba(255,255,255,.4),transparent),
               radial-gradient(1px 1px at 30% 60%,rgba(255,255,255,.3),transparent),
               radial-gradient(1px 1px at 50% 10%,rgba(255,255,255,.5),transparent),
               radial-gradient(1px 1px at 70% 80%,rgba(255,255,255,.3),transparent),
               radial-gradient(1px 1px at 90% 40%,rgba(255,255,255,.4),transparent),
               radial-gradient(1.5px 1.5px at 15% 85%,rgba(255,255,255,.5),transparent),
               radial-gradient(1px 1px at 85% 15%,rgba(255,255,255,.3),transparent),
               radial-gradient(1px 1px at 45% 45%,rgba(255,255,255,.4),transparent),
               radial-gradient(1.5px 1.5px at 65% 30%,rgba(255,255,255,.6),transparent);
    pointer-events:none;
  }

  header{
    position:relative;z-index:1;
    text-align:center;padding:3rem 1.5rem 2rem;
    background:linear-gradient(180deg,rgba(17,24,39,.9),transparent);
  }
  header h1{
    font-size:2.2rem;font-weight:800;
    background:linear-gradient(135deg,#60a5fa,#a78bfa,#f472b6);
    -webkit-background-clip:text;-webkit-text-fill-color:transparent;
    background-clip:text;margin-bottom:.5rem;
  }
  header p{color:var(--text-dim);font-size:1rem;max-width:600px;margin:0 auto}

  /* Earth cross-section diagram */
  .diagram-section{
    position:relative;z-index:1;
    display:flex;justify-content:center;align-items:center;
    padding:2rem 1rem;
  }
  .diagram-wrap{position:relative;width:420px;height:420px;max-width:90vw;max-height:90vw}

  svg .layer{transition:opacity .3s;cursor:pointer}
  svg .layer:hover{opacity:.85}

  .legend{
    position:relative;z-index:1;
    display:flex;justify-content:center;gap:2rem;flex-wrap:wrap;
    padding:0 1rem 1rem;
  }
  .legend-item{display:flex;align-items:center;gap:.4rem;font-size:.85rem;color:var(--text-dim)}
  .legend-dot{width:12px;height:12px;border-radius:50%}

  /* Content cards */
  main{
    position:relative;z-index:1;
