fun formatShutterSpeed(exposureTimeNs: Long): String {

[Showing lines 1-1120 of 1145 (50.0KB limit). Use offset=1121 to continue.]

    if (exposureTimeNs <= 0) return "--"
    val exposureTimeSec = exposureTimeNs / 1_000_000_000.0
    return when {
        exposureTimeSec < 1.0 -> {
            val denominator = (1.0 / exposureTimeSec).roundToInt()
            val reciprocal = 1.0 / denominator
            if (kotlin.math.abs(reciprocal - exposureTimeSec) < 0.001 && denominator >= 2) {
                "1/$denominator"
            } else {
                String.format("%.2f", exposureTimeSec)
            }
        }
        else -> {
            if (exposureTimeSec >= 100.0) String.format("%ds", exposureTimeSec.toInt())
            else if (exposureTimeSec >= 10.0) String.format("%.1fs", exposureTimeSec)
            else String.format("%.2fs", exposureTimeSec)
        }
    }
}

fun Context.findActivity(): androidx.activity.ComponentActivity? = when (this) {
    is androidx.activity.ComponentActivity -> this
    is android.content.ContextWrapper -> baseContext.findActivity()
    else -> null
}

