@Composable
private fun LensSelector(
    cameras: List<CameraInfo>,
    selectedCameraId: String,
    selectedPhysicalId: String?,
    onCameraSelected: (String, String?) -> Unit,
    modifier: Modifier = Modifier
) {
    Row(modifier = modifier) {
        val frontCamera = cameras.find { it.facing == CameraCharacteristics.LENS_FACING_FRONT }
        if (frontCamera != null) {
            val isSelected = selectedCameraId == frontCamera.id && selectedPhysicalId == null
            CameraButton(
                label = "F",
                isSelected = isSelected,
                onClick = { onCameraSelected(frontCamera.id, null) }
            )
        }

        val physicalCameras = cameras.filter { it.isPhysical }.distinctBy { it.zoomLabel }
        physicalCameras.forEach { cam ->
            val isSelected = selectedPhysicalId == cam.physicalId
            CameraButton(
                label = cam.zoomLabel,
                isSelected = isSelected,
                onClick = { onCameraSelected(cam.id, cam.physicalId) }
            )
        }
    }
}

@Composable
private fun CameraButton(
