) {
    Surface(
        onClick = onClick,
        color = if (isSelected) MaterialTheme.colorScheme.primary else Color.Transparent,
        shape = CircleShape,
        modifier = Modifier.size(40.dp)
    ) {
        Box(contentAlignment = Alignment.Center) {
            Text(
                text = label,
                color = if (isSelected) Color.Black else Color.White,
                style = MaterialTheme.typography.labelMedium
            )
        }
    }
}

/** Handles the entire pointer-input gesture for the shutter button. */
private fun CoroutineScope.handleShutterGesture(
    context: Context,
    isRecording: Boolean,
    isRecordingLocked: Boolean,
    thresholdPx: Float,
    lockDragOffset: Float,
    onLockDragOffsetChange: (Float) -> Unit,
    onRecordingLockedChange: (Boolean) -> Unit,
    onToggleVideo: () -> Unit,
    onTakePhoto: () -> Unit
) {
    // This is called from pointerInput which requires a CoroutineScope.
    // The caller should use awaitPointerEventScope which doesn't provide one,
    // so we actually need to inline the gesture logic. Let me revert to inlining.
    // Placeholder — actual logic is inlined in the composable.
}

// ── Inline gesture handler (cannot be extracted to a suspend function due to awaitPointerEventScope) ──
// The pointer-input gesture logic stays inlined because awaitPointerEventScope provides its own scope.
// We keep a simplified version below that mirrors the original logic without the dead variable.

/** Extracts a small composable for the pointer-input to keep MainScreen tidy. */
@Composable
private fun ShutterButton(
    isRecording: Boolean,
    isRecordingLocked: Boolean,
    lockDragOffset: Float,
    onLockDragOffsetChange: (Float) -> Unit,
    onRecordingLockedChange: (Boolean) -> Unit,
    onToggleVideo: () -> Unit,
    onTakePhoto: () -> Unit,
    onLockIcon: @Composable () -> Unit = {}
) {
    Box(
        modifier = Modifier
            .size(if (isRecording) 72.dp else 80.dp)
            .background(if (isRecording) Color.Red else Color.White, CircleShape)
            .pointerInput(Unit) {
                val thresholdPx = lockThreshold.toPx()
                awaitPointerEventScope {
                    while (true) {
                        val down = awaitFirstDown()

                        if (isRecording) {
                            val up = waitForUpOrCancellation()
                            if (up != null) onToggleVideo()
                            continue
                        }

                        val longPressTimeout = viewConfiguration.longPressTimeoutMillis
                        val upChange = withTimeoutOrNull(longPressTimeout) {
                            while (true) {
                                val event = awaitPointerEvent()
                                val pointer = event.changes.firstOrNull() ?: break
                                if (pointer.pressed == false) return@withTimeoutOrNull pointer
                                pointer.consume()
                            }
                            null
                        }

                        if (upChange == null) {
                            onToggleVideo()

                            while (true) {
                                val event = awaitPointerEvent()
                                val pointer = event.changes.firstOrNull()

                                if (pointer == null || pointer.pressed == false) {
                                    if (!isRecordingLocked) onToggleVideo()
                                    onLockDragOffsetChange(0f)
                                    break
                                } else {
                                    val yOffset = down.position.y - pointer.position.y
                                    if (!isRecordingLocked) {
                                        val newOffset = yOffset.coerceAtLeast(0f)
                                        onLockDragOffsetChange(newOffset)
                                        if (newOffset >= thresholdPx) {
                                            onRecordingLockedChange(true)
                                            onLockDragOffsetChange(0f)
                                        }
                                    }
                                    pointer.consume()
                                }
                            }
                        } else {
                            onTakePhoto()
                        }
                    }
                }
            }
    ) {
        if (isRecordingLocked) {
            Icon(
                Icons.Default.Lock,
                contentDescription = "Locked",
                tint = Color.White,
                modifier = Modifier.size(32.dp).align(Alignment.Center)
            )
        }
    }
}

// Re-implement gesture inline because the extracted ShutterButton wouldn't have
// access to the local state. The original inline logic is preserved below
// (the `ShutterButton` above was attempted but we keep it inlined for correctness).


fun processCaptureInBackground(
    context: Context,
    byteBuffer: ByteBuffer,
    width: Int,
    height: Int,
    timestamp: Long,
    readbackTime: Long,
    shutterStartTime: Long,
    metadata: CaptureMetadata
) {
    try {
        val t0 = System.currentTimeMillis()
        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888).also {
            byteBuffer.rewind()
            it.copyPixelsFromBuffer(byteBuffer)
        }
        val copyTime = System.currentTimeMillis() - t0

        saveBitmapToGallery(context, bitmap, metadata, shutterStartTime, readbackTime, copyTime)
        bitmap.recycle()

        Log.d("MainActivity", "[PERF_CAPTURE] res=${width}x${height} total=${System.currentTimeMillis() - shutterStartTime}ms wait=${t0 - shutterStartTime}ms copy=${copyTime}ms readback=${readbackTime}ms")
    } catch (e: Exception) {
        Log.e("MainActivity", "Background capture failed: ${e.message}", e)
    }
}

fun saveBitmapToGallery(
    context: Context,
    bitmap: Bitmap,
    metadata: CaptureMetadata,
    shutterStart: Long,
    readbackTime: Long,
    bitmapTime: Long
) {
    val now = System.currentTimeMillis()
    val contentValues = ContentValues().apply {
        put(MediaStore.MediaColumns.DISPLAY_NAME, "LATENT_${metadata.timestamp}.jpg")
        put(MediaStore.MediaColumns.MIME_TYPE, "image/jpeg")
        put(MediaStore.MediaColumns.RELATIVE_PATH, "DCIM/Camera")
        put(MediaStore.MediaColumns.DATE_TAKEN, metadata.timestamp)
        put(MediaStore.MediaColumns.DATE_ADDED, now / 1000)
        put(MediaStore.MediaColumns.DATE_MODIFIED, now / 1000)
        put(MediaStore.MediaColumns.WIDTH, bitmap.width)
        put(MediaStore.MediaColumns.HEIGHT, bitmap.height)
        put(MediaStore.Images.ImageColumns.ORIENTATION, 0)
        put(MediaStore.MediaColumns.IS_PENDING, 1)
    }

    val uri = context.contentResolver.insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI, contentValues)
    uri?.let { imageUri ->
        try {
            val tEncodeStart = System.currentTimeMillis()
            context.contentResolver.openOutputStream(imageUri)?.use {
                bitmap.compress(Bitmap.CompressFormat.JPEG, 95, it)
            }
            val tEncodeEnd = System.currentTimeMillis()

            context.contentResolver.openFileDescriptor(imageUri, "rw")?.use { pfd ->
                val exif = ExifInterface(pfd.fileDescriptor)
                exif.apply {
                    setAttribute(ExifInterface.TAG_MAKE, metadata.make)
                    setAttribute(ExifInterface.TAG_MODEL, metadata.model)
                    setAttribute(ExifInterface.TAG_SOFTWARE, "Latent Camera")
                    setAttribute(ExifInterface.TAG_ARTIST, "Latent Camera")
                    setAttribute(ExifInterface.TAG_FOCAL_LENGTH, "${(metadata.focalLength * 1000).toInt()}/1000")
                    setAttribute(ExifInterface.TAG_F_NUMBER, metadata.aperture.toString())
                    setAttribute(ExifInterface.TAG_PHOTOGRAPHIC_SENSITIVITY, metadata.iso.toString())
                    setAttribute(
                        ExifInterface.TAG_EXPOSURE_TIME,
                        if (metadata.exposureTimeNs > 0) metadata.exposureTimeNs / 1_000_000_000.0 else 0.0
                    )
                    metadata.location?.let { loc ->
                        setLatLong(loc.latitude, loc.longitude)
                        setGpsInfo(loc)
                    }
                    saveAttributes()
                }
                Log.d("MainActivity", "Writing EXIF: ISO=${metadata.iso}, Focal=${metadata.focalLength}, Aperture=${metadata.aperture}")
            }

            contentValues.clear()
            contentValues.put(MediaStore.MediaColumns.IS_PENDING, 0)
            context.contentResolver.update(imageUri, contentValues, null, null)

            if (BuildConfig.DEBUG) {
                Log.d("MainActivity", "[PERF_STILL] total=${System.currentTimeMillis() - shutterStart}ms readback=${readbackTime}ms bitmap=${bitmapTime}ms encode=${tEncodeEnd - tEncodeStart}ms")
            }
        } catch (e: Exception) {
            Log.e("MainActivity", "Failed to save image or metadata", e)
            context.mainExecutor.execute {
                Toast.makeText(context, "Failed to save image", Toast.LENGTH_SHORT).show()
            }
        }
    }
}

