fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "--"
    val exposureTimeSec = exposureTimeNs / 1_000_000_000.0
    return when {
        exposureTimeSec < 1.0 -> {
            val denominator = (1.0 / exposureTimeSec).roundToInt()
            if (kotlin.math.abs(1.0 / denominator - exposureTimeSec) < 0.001 && denominator >= 2) {
                "1/$denominator"
            } else {
                String.format("%.2f", exposureTimeSec)
            }
        }
        else -> {
            when {
                exposureTimeSec >= 100.0 -> String.format("%ds", exposureTimeSec.toInt())
                exposureTimeSec >= 10.0 -> String.format("%.1fs", exposureTimeSec)
                else -> String.format("%.2fs", exposureTimeSec)
            }
        }
    }
}

