No castling, en passant, promotion, or check/pin filtering.
"""

from __future__ import annotations

import copy
import typing as T

from typing import Literal

# ── piece / colour helpers ──────────────────────────────────────────────
WHITE = "w"
BLACK = "b"

PIECE_CHARS = {"K": 1, "Q": 2, "R": 3, "B": 4, "N": 5, "P": 6,
               "k": -1, "q": -2, "r": -3, "b": -4, "n": -5, "p": -6}

def colour(piece: int) -> str:
    return WHITE if piece > 0 else BLACK

def is_own(piece: int, side: str) -> bool:
    return (piece > 0) == (side == WHITE)

def is_empty(piece: int) -> bool:
    return piece == 0


# ── board representation ───────────────────────────────────────────────
# 64 ints, index = 8*rank + file  (rank 0-7 = 1-8, file 0-7 = a-h)
# board[0] = a1, board[7] = h1, board[56] = a8 … board[63] = h8


def parse_fen(fen: str) -> tuple[list[int], str, T.Any, T.Any]:
    """Return (board, active_colour, castling, ep_square).
    ep_square is (rank, file) or None.
    Castling / ep are accepted but *not* enforced – they sit in for
    structural completeness only (movegen ignores them so far).
    """
    parts = fen.split()
    board_str = parts[0]
    active = parts[1]

    # castling
    castling = parts[2] if len(parts) > 2 else "-"

    # en passant  "e3" → (rank=2, file=4)
    ep_raw = parts[3] if len(parts) > 3 else "-"
    if ep_raw != "-":
        file = ord(ep_raw[0]) - ord("a")
        rank = int(ep_raw[1]) - 1
        ep = (rank, file)
    else:
        ep = None

    board: list[int] = [0] * 64
    row, col = 0, 0
    for ch in board_str:
        if ch == "/":
            row += 1
            col = 0
        elif ch.isdigit():
            col += int(ch)
        else:
            idx = row * 8 + col
            board[idx] = PIECE_CHARS[ch]
            col += 1

    return board, active, castling, ep


def to_uci(file: int, rank: int) -> str:
    return f"{chr(ord('a') + file)}{rank + 1}"


# ── move generation helpers ────────────────────────────────────────────

# (row, col) deltas for sliding pieces, indexed by piece type:
#   -K,-Q,-R,-B,-N,-P,+P,+N,+B,+R,+Q,+K
SLIDER_PATHS: dict[int, list[tuple[int, int]]] = {
    3: [(1, 0), (-1, 0), (0, 1), (0, -1)],       # Rook
    4: [(1, 1), (1, -1), (-1, 1), (-1, -1)],     # Bishop
    2: [(1, 0), (-1, 0), (0, 1), (0, -1),        # Queen
        (1, 1), (1, -1), (-1, 1), (-1, -1)],
}

KNIGHT_OFFSETS = [(2, 1), (2, -1), (-2, 1), (-2, -1),
                  (1, 2), (1, -2), (-1, 2), (-1, -2)]

PAWN_FORWARD: dict[str, tuple[int, int]] = {
    "w": (-1, 0),  # up the board (decreasing rank index)
    "b": (1, 0),
}


def _in_bounds(r: int, c: int) -> bool:
    return 0 <= r < 8 and 0 <= c < 8


def _generate_moves(
    board: list[int],
    side: str,
) -> list[str]:
    moves: list[str] = []

    for idx, piece in enumerate(board):
        if piece == 0:
            continue
        if not is_own(piece, side):
            continue

        piece_type = abs(piece)
        r, c = divmod(idx, 8)

        # ── pawns ────────────────────────────────────────────────────
        if piece_type == 6:
            fwd_r, _ = PAWN_FORWARD[side]

            # single push
            nr, nc = r + fwd_r, c
            if _in_bounds(nr, nc):
                target = board[nr * 8 + nc]
                if is_empty(target):
                    moves.append(f"{to_uci(c, r)}{to_uci(nc, nr)}")

            # double push from starting rank
            start_rank = 1 if side == WHITE else 6
            if r == start_rank:
                dr = fwd_r * 2
                nr, nc = r + dr, c
                mid = (r + fwd_r) * 8 + c
                if is_empty(board[mid]) and is_empty(board[nr * 8 + nc]):
                    moves.append(f"{to_uci(c, r)}{to_uci(nc, nr)}")

            # captures (diagonals only)
            for dc in (-1, 1):
                nr, nc = r + fwd_r, c + dc
                if _in_bounds(nr, nc):
